#include "content.hpp"
#include "replay.hpp"
#include "vegetation.hpp"
#include <set>
#include <iostream>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("real data directory required");Resources r(fs::u8path(argv[1]));auto lang=language_strings(r);if(lang.size()<900||lang.at("INGAME_MENU_ITEM_CONTINUE_RACE").empty())throw std::runtime_error("original language table");auto cars=car_catalog(r);auto stages=stage_catalog(r);auto menu=music_catalog(r,true),race=music_catalog(r,false);if(cars.size()!=16||stages.size()<40||menu.size()!=1||race.size()!=26)throw std::runtime_error("content catalog counts");for(auto&car:cars){auto cfg=load_vehicle(r,car.id,argc>2?argv[2]:"");if(cfg.mass<=0||cfg.ratios.empty()||cfg.torque_curve.empty()||cfg.max_rpm<=cfg.idle_rpm)throw std::runtime_error("car configuration");auto tire=load_geometry(r,cfg.tire);Geometry floor;floor.materials.push_back({});Mesh mesh;mesh.vertices={{{-1000,0,-1000}},{{1000,0,-1000}},{{1000,0,1000}},{{-1000,0,1000}}};mesh.indices={0,2,1,0,3,2};floor.meshes.push_back(mesh);Simulation sim(floor,cfg,translate({0,1,0}));for(int i=0;i<300;++i)sim.step({});for(int i=0;i<200;++i){Input input;input.throttle=1;sim.step(input);}if(!std::isfinite(sim.state().speed)||std::abs(sim.state().speed)<.5)throw std::runtime_error("stock car drive failed: "+car.name);std::cout<<car.id<<" "<<cfg.name<<" mass="<<cfg.mass<<" gears="<<cfg.ratios.size()<<" skins="<<car.skins.size()<<" tire="<<cfg.tire<<'\n';}
std::set<std::string> geometry;size_t plants_total=0;for(auto&stage:stages){auto path=stage_geometry(stage);if(geometry.insert(path).second){auto g=load_geometry(r,path);if(!g.triangles)throw std::runtime_error("empty stage geometry");}auto plants=load_vegetation(r,path,stage);if(!plants.error.empty())throw std::runtime_error(plants.source+": "+plants.error);plants_total+=plants.sprites.size();auto spawn=load_spawn(r,stage);if(!std::isfinite(spawn[13]))throw std::runtime_error("spawn");}
Replay replay;for(int i=0;i<60002;i++){State s;s.time=i*.01;replay.record(s);}replay.begin();if(replay.diagnostics()["frames"]!=60000||replay.sample().time!=.02)throw std::runtime_error("bounded replay");replay.tick(.1);replay.toggle();auto old=replay.sample().time;replay.tick(.1);if(old!=replay.sample().time)throw std::runtime_error("replay paused");std::cout<<geometry.size()<<" unique track geometries; "<<plants_total<<" stage plant records; "<<cars.size()<<" cars; "<<stages.size()<<" stages; "<<menu.size()<<" menu / "<<race.size()<<" race tracks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
